import { CustomerForm } from './components/CustomerForm';
import { AdminDashboard } from './components/AdminDashboard';
import { TrackingView } from './components/TrackingView';
import { LoginView } from './components/LoginView';
import { FeaturedBusinesses } from './components/FeaturedBusinesses';
import { Ticket, TicketStatus, ViewState, ServiceOption, Personnel, Customer, AppConfig, FormField, TimelineEntry, InternalMessage, Task, Meeting, KPI } from './types';
import { IconLayout, IconPlus, IconSearch, IconShield, IconBulb, IconRefreshCw, IconAlertTriangle, IconCheck } from './components/Icons';
import { 
  saveTicketToCloud, updateTicketInCloud, deleteTicketFromCloud,
  saveCustomerToCloud, saveCustomersBulkToCloud, updateCustomerInCloud, deleteCustomerFromCloud,
  saveAppConfigToCloud,
  saveServicesToCloud,
  savePersonnelToCloud,
  subscribeToTickets, subscribeToCustomers, subscribeToSettings,
  subscribeToMessages, subscribeToTasks, subscribeToMeetings, subscribeToKPIs, sanitizeData, logSystemAction, checkDatabaseConnection
} from './services/firebaseService';

// Translations Dictionary
export type Language = 'fa' | 'en';

export const DICTIONARY = {
  fa: {
    startBtn: 'شروع مشاوره و خدمات',
    trackBtn: 'پیگیری وضعیت پرونده',
    newTicket: 'ثبت درخواست',
    tracking: 'پیگیری',
    expertPanel: 'پنل کارشناسان',
    home: 'خانه',
    footer: '© 1403 پلتفرم جامع خدمات صادراتی. تمامی حقوق محفوظ است.',
    features: [
      { title: 'ارسال آنلاین مدارک', desc: 'بارگذاری کاتالوگ، عکس و ویدیو جهت بررسی کارشناسان' },
      { title: 'تحلیل هوشمند بازار', desc: 'استفاده از هوش مصنوعی برای ارزیابی پتانسیل محصول' },
      { title: 'پیگیری مرحله به مرحله', desc: 'اطلاع از وضعیت دقیق درخواست در پنل کاربری' },
    ],
    alertSuccess: 'درخواست شما با موفقیت ثبت شد.\nشماره پیگیری: ',
    landingSubtitle: 'اولین و بزرگترین پلتفرم هوشمند خدمات صادراتی و بازرگانی کشور. با ما مسیر ورود به بازارهای جهانی را هموار کنید.',
    dbStatus: {
        online: 'سرور متصل است',
        offline: 'قطع ارتباط',
        connecting: 'در حال اتصال...'
    }
  },
  en: {
    startBtn: 'Start Services',
    trackBtn: 'Track Request',
    newTicket: 'New Request',
    tracking: 'Tracking',
    expertPanel: 'Staff Login',
    home: 'Home',
    footer: '© 2024 Comprehensive Export Platform. All rights reserved.',
    features: [
      { title: 'Online Submission', desc: 'Upload documents for expert review' },
      { title: 'AI Market Analysis', desc: 'Smart evaluation of product potential' },
      { title: 'Live Tracking', desc: 'Track your request status in real-time' },
    ],
    alertSuccess: 'Your request has been submitted successfully.\nTracking ID: ',
    landingSubtitle: 'The leading smart export and trade services platform. Paving your path to global markets.',
    dbStatus: {
        online: 'Connected',
        offline: 'Offline',
        connecting: 'Connecting...'
    }
  }
};

// Default Services
const DEFAULT_SERVICES: ServiceOption[] = [
  { 
    id: 's1', 
    title: 'مشاوره تخصصی صادرات', titleEn: 'Expert Export Consultation',
    description: 'مشاوره ورود به بازار و قوانین گمرکی', descriptionEn: 'Market entry strategy and customs regulations',
    icon: '🌍', isActive: true, price: { amount: 5000000, currency: 'IRR' }
  },
  { 
    id: 's4', 
    title: 'طراحی گرافیک و کاتالوگ', titleEn: 'Graphic Design & Catalog',
    description: 'تولید محتوای بصری بین‌المللی', descriptionEn: 'International visual content production',
    icon: '🎨', isActive: true, price: { amount: 15000000, currency: 'IRR' }
  }
];

const DEFAULT_PERSONNEL: Personnel[] = [
  { 
    id: 'p_master', 
    fullName: 'Master Admin', 
    roles: ['مدیر'], 
    email: 'master@export.com', 
    username: 'master', 
    password: 'MasterAdmin2024', 
    status: 'active',
    permissions: { canAssign: true, canViewCustomers: true, canViewTariffs: true, canViewAllTickets: true, canIssueInvoices: true }
  },
];

const INITIAL_CONFIG: AppConfig = {
  appTitle: 'پلتفرم جامع صادراتی',
  appTitleEn: 'Export Platform',
  appSubtitle: 'مشاوره، توسعه بازار و خدمات بازرگانی',
  appSubtitleEn: 'Consultancy, Market Development & Trade Services',
  formFields: [],
  assignmentConfig: { mode: 'manual', serviceRoleMap: {} }
};

const STORAGE_KEYS = {
  USER: 'crm_session_user',
  VIEW: 'crm_last_view',
  LAST_ACTIVE: 'crm_last_active'
};

const App: React.FC = () => {
  const [view, setViewState] = useState<ViewState>('landing');
  const [lang, setLang] = useState<Language>('fa');
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [services, setServices] = useState<ServiceOption[]>(DEFAULT_SERVICES);
  const [personnel, setPersonnel] = useState<Personnel[]>(DEFAULT_PERSONNEL);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [messages, setMessages] = useState<InternalMessage[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [meetings, setMeetings] = useState<Meeting[]>([]);
  const [kpis, setKpis] = useState<KPI[]>([]);
  const [currentUser, setCurrentUser] = useState<Personnel | null>(null);
  const [appConfig, setAppConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [isLoadingData, setIsLoadingData] = useState(true);

  // Connection Status State
  const [connectionStatus, setConnectionStatus] = useState<'connecting' | 'online' | 'offline'>('connecting');

  const t = DICTIONARY[lang];

  const setView = (newView: ViewState) => {
    setViewState(newView);
    localStorage.setItem(STORAGE_KEYS.VIEW, newView);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCheckConnection = useCallback(async () => {
      setConnectionStatus('connecting');
      const isOnline = await checkDatabaseConnection();
      setConnectionStatus(isOnline ? 'online' : 'offline');
      return isOnline;
  }, []);

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
  }, [lang]);

  useEffect(() => {
    handleCheckConnection();

    const unsubTickets = subscribeToTickets((data) => {
      setTickets(data);
      setIsLoadingData(false);
      setConnectionStatus('online');
    });

    const unsubCustomers = subscribeToCustomers((data) => {
      setCustomers(data);
    });

    const unsubMessages = subscribeToMessages((data) => {
        setMessages(data);
    });

    const unsubTasks = subscribeToTasks((data) => {
        setTasks(data);
    });

    const unsubMeetings = subscribeToMeetings((data) => {
        setMeetings(data);
    });

    const unsubKPIs = subscribeToKPIs((data) => {
        setKpis(data);
    });

    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) setPersonnel(ppl); }
    );

    return () => {
      unsubTickets();
      unsubCustomers();
      unsubSettings();
      unsubMessages();
      unsubTasks();
      unsubMeetings();
      unsubKPIs();
    };
  }, [handleCheckConnection]);

  /**
   * تابع کمکی برای پیدا کردن کارشناس مناسب براساس تنظیمات سیستم
   */
  const calculateAutoAssignee = useCallback((serviceId: string): string => {
      const config = appConfig.assignmentConfig;
      if (!config || config.mode === 'manual') return '';

      const targetRole = config.serviceRoleMap[serviceId];
      if (!targetRole) return '';

      // فیلتر کردن پرسنلی که نقش مورد نظر را دارند و فعال هستند
      const candidates = personnel.filter(p => p.roles.includes(targetRole) && p.status === 'active');
      if (candidates.length === 0) return '';

      // حالت رندوم
      if (config.mode === 'random') {
          return candidates[Math.floor(Math.random() * candidates.length)].id;
      }

      // حالت توزیع بار (کمترین کار باز)
      if (config.mode === 'auto_load_balance') {
          const loadMap = candidates.map(p => {
              const openTickets = tickets.filter(t => 
                  t.assignedTo === p.id && 
                  t.status !== TicketStatus.COMPLETED && 
                  t.status !== TicketStatus.CANCELLED
              ).length;
              return { id: p.id, count: openTickets };
          });
          // سورت بر اساس کمترین تعداد تیکت
          loadMap.sort((a, b) => a.count - b.count);
          return loadMap[0].id;
      }

      return '';
  }, [appConfig, personnel, tickets]);

  const handleLogin = async (u: string, p: string): Promise<boolean> => {
    const user = personnel.find(person => person.username === u && person.password === p);
    if (user) {
      setCurrentUser(user);
      logSystemAction('LOGIN', 'System', 'ورود کاربر به سیستم', user.fullName, user.id);
      localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(sanitizeData(user)));
      localStorage.setItem(STORAGE_KEYS.LAST_ACTIVE, Date.now().toString());
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setView('landing');
    localStorage.removeItem(STORAGE_KEYS.USER);
    localStorage.removeItem(STORAGE_KEYS.VIEW);
    localStorage.removeItem(STORAGE_KEYS.LAST_ACTIVE);
  };

  const handleNewTicket = async (ticketOrTickets: Ticket | Ticket[]) => {
      const ticketsToSave = Array.isArray(ticketOrTickets) ? ticketOrTickets : [ticketOrTickets];
      for (const t of ticketsToSave) {
          // اعمال ارجاع خودکار قبل از ذخیره
          const autoAssignee = calculateAutoAssignee(t.serviceId);
          const finalTicket = { ...t };
          if (autoAssignee) {
              finalTicket.assignedTo = autoAssignee;
              // اضافه کردن رویداد ارجاع به تایم‌لاین
              const assignedPerson = personnel.find(p => p.id === autoAssignee);
              if (assignedPerson) {
                  finalTicket.timeline.push({
                      type: 'assignment',
                      title: 'ارجاع خودکار سیستمی',
                      description: `پرونده به صورت خودکار به ${assignedPerson.fullName} ارجاع شد.`,
                      actorName: 'سیستم هوشمند',
                      timestamp: new Date().toISOString(),
                      visibility: 'internal'
                  });
              }
          }
          await saveTicketToCloud(finalTicket);
      }
  };

  const NavItem = ({ active, label, icon, onClick }: any) => (
    <button
      onClick={onClick}
      className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${
        active 
          ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200' 
          : 'text-gray-600 hover:bg-gray-100'
      }`}
    >
      {icon}
      <span className="font-medium">{label}</span>
    </button>
  );

  const MobileNavItem = ({ active, label, icon, onClick }: any) => (
    <button
      onClick={onClick}
      className={`flex flex-col items-center justify-center gap-1 flex-1 py-2 transition-all ${
        active ? 'text-indigo-600' : 'text-gray-400'
      }`}
    >
      <div className={`p-1.5 rounded-xl transition-all ${active ? 'bg-indigo-50' : ''}`}>
        {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
      </div>
      <span className="text-[10px] font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen bg-gray-50 flex flex-col font-sans ${lang === 'fa' ? 'font-vazir' : ''}`} dir={lang === 'fa' ? 'rtl' : 'ltr'}>

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
               <IconShield className="w-6 h-6" />
            </div>
            <div className="hidden sm:block">
              <h1 className="text-xl font-bold text-gray-900 leading-tight">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1>
              <p className="text-[10px] text-gray-500">{lang === 'fa' ? appConfig.appSubtitle : appConfig.appSubtitleEn}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div 
              title={connectionStatus === 'online' ? t.dbStatus.online : (connectionStatus === 'connecting' ? t.dbStatus.connecting : t.dbStatus.offline)}
              onClick={connectionStatus === 'offline' ? handleCheckConnection : undefined}
              className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-sm cursor-help transition-all ${
                connectionStatus === 'online' 
                  ? 'bg-green-500 animate-pulse shadow-green-200' 
                  : connectionStatus === 'connecting'
                    ? 'bg-yellow-400 animate-bounce'
                    : 'bg-red-500 shadow-red-200 cursor-pointer'
              }`}
            ></div>

            <nav className="hidden md:flex gap-2">
              <NavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus className="w-4 h-4" />} onClick={() => setView('new-ticket')} />
              <NavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch className="w-4 h-4" />} onClick={() => setView('tracking')} />
              <NavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout className="w-4 h-4" />} onClick={() => setView('admin')} />
            </nav>

            <div className="flex border border-gray-200 rounded-lg overflow-hidden bg-white">
               <button onClick={() => setLang('fa')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'fa' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500 hover:bg-gray-50'}`}>FA</button>
               <div className="w-px bg-gray-200"></div>
               <button onClick={() => setLang('en')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'en' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500 hover:bg-gray-50'}`}>EN</button>
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full pb-24 md:pb-8">
        {isLoadingData && view !== 'landing' ? (
           <div className="flex items-center justify-center h-64">
               <div className="text-gray-500 flex flex-col items-center gap-2">
                  <div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                  <span>در حال دریافت اطلاعات از سرور...</span>
               </div>
           </div>
        ) : (
          <>
            {view === 'landing' && (
              <div className="animate-fade-in text-center py-12 md:py-20">
                <h2 className="text-3xl md:text-6xl font-black text-gray-900 mb-6 leading-tight whitespace-pre-line px-4">{lang === 'fa' ? (appConfig.landingHeroTitle || 'مسیر جهانی شدن کسب‌وکار شما') : 'Globalize Your Business'}</h2>
                <p className="text-lg md:text-xl text-gray-600 mb-12 max-w-2xl mx-auto leading-relaxed whitespace-pre-line px-6">{lang === 'fa' ? (appConfig.landingHeroSubtitle || t.landingSubtitle) : t.landingSubtitle}</p>
                <div className="flex flex-col sm:flex-row gap-4 justify-center px-6">
                  <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl hover:scale-105 transition-transform">{t.startBtn}</button>
                  <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold hover:bg-gray-50 transition-colors">{t.trackBtn}</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-16 md:mt-24 px-4">
                  {t.features.map((f, i) => (
                    <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 group hover:border-indigo-200 transition-colors">
                        <div className="text-4xl mb-4 group-hover:scale-110 transition-transform">{[ '📂', '🌍', '📊'][i]}</div>
                        <h3 className="font-bold text-lg mb-2">{f.title}</h3>
                        <p className="text-gray-500 text-sm leading-relaxed">{f.desc}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {view === 'new-ticket' && (
              <CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} lang={lang} />
            )}

            {view === 'tracking' && (
              <TrackingView tickets={tickets} services={services} lang={lang} />
            )}

            {view === 'admin' && (
              <>
                {!currentUser ? (
                  <LoginView onLogin={handleLogin} onBack={() => setView('landing')} />
                ) : (
                  <AdminDashboard 
                    lang={lang}
                    currentUser={currentUser}
                    tickets={tickets} 
                    services={services}
                    personnel={personnel}
                    customers={customers}
                    messages={messages}
                    tasks={tasks}
                    meetings={meetings}
                    kpis={kpis}
                    config={appConfig}
                    onCreateTicket={async (t) => handleNewTicket(t)} 
                    onUpdateTicket={async (id, updates, actor, note, visibility) => {
                        const ticket = tickets.find(t => t.id === id);
                        if (!ticket) return;

                        // ایجاد رویداد جدید در تایم‌لاین برای ثبت در تاریخچه
                        const newTimelineEntry: TimelineEntry = {
                            type: updates.assignedTo ? 'assignment' : (updates.status ? 'status_change' : 'comment'),
                            title: updates.assignedTo ? 'ارجاع پرونده' : (updates.status ? `تغییر وضعیت به ${updates.status}` : 'بروزرسانی اطلاعات'),
                            description: note || '',
                            actorName: actor,
                            timestamp: new Date().toISOString(),
                            visibility: visibility || 'public'
                        };

                        const finalUpdates = {
                            ...updates,
                            timeline: [...(ticket.timeline || []), newTimelineEntry]
                        };

                        await updateTicketInCloud(id, finalUpdates);
                    }}
                    onDeleteTicket={deleteTicketFromCloud}
                    onUpdateServices={saveServicesToCloud}
                    onUpdatePersonnel={savePersonnelToCloud}
                    onUpdateCustomers={() => {}}
                    onEditCustomer={updateCustomerInCloud}
                    onDeleteCustomer={deleteCustomerFromCloud}
                    onUpdateConfig={saveAppConfigToCloud}
                    onLogout={handleLogout}
                  />
                )}
              </>
            )}
          </>
        )}
      </main>

      {/* Footer */}
      <footer className="hidden md:block bg-white border-t border-gray-200 py-8 text-center text-gray-500 text-sm">
        <p>{appConfig.footerText || t.footer}</p>
      </footer>

      {/* Mobile Bottom Navigation */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-200 px-2 py-1 flex items-center justify-around z-[60] shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <MobileNavItem 
          active={view === 'landing'} 
          label={t.home} 
          icon={<IconBulb />} 
          onClick={() => setView('landing')} 
        />
        <MobileNavItem 
          active={view === 'new-ticket'} 
          label={t.newTicket} 
          icon={<IconPlus />} 
          onClick={() => setView('new-ticket')} 
        />
        <MobileNavItem 
          active={view === 'tracking'} 
          label={t.tracking} 
          icon={<IconSearch />} 
          onClick={() => setView('tracking')} 
        />
        <MobileNavItem 
          active={view === 'admin'} 
          label={t.expertPanel} 
          icon={<IconLayout />} 
          onClick={() => setView('admin')} 
        />
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
