      <header className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg">
               <IconShield className="w-6 h-6" />
            </div>
            <div className="hidden sm:block">
              <h1 className="text-xl font-bold text-gray-900 leading-tight">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1>
              <p className="text-[10px] text-gray-500">{lang === 'fa' ? appConfig.appSubtitle : appConfig.appSubtitleEn}</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div 
              title={connectionStatus === 'online' ? t.dbStatus.online : (connectionStatus === 'connecting' ? t.dbStatus.connecting : t.dbStatus.offline)}
              onClick={connectionStatus === 'offline' ? handleCheckConnection : undefined}
              className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-sm cursor-help transition-all ${
                connectionStatus === 'online' 
                  ? 'bg-green-500 animate-pulse shadow-green-200' 
                  : connectionStatus === 'connecting'
                    ? 'bg-yellow-400 animate-bounce'
                    : 'bg-red-500 shadow-red-200 cursor-pointer'
              }`}
            ></div>

            <nav className="hidden md:flex gap-2">
              <NavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus className="w-4 h-4" />} onClick={() => setView('new-ticket')} />
              <NavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch className="w-4 h-4" />} onClick={() => setView('tracking')} />
              <NavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout className="w-4 h-4" />} onClick={() => setView('admin')} />
            </nav>

            <div className="flex border border-gray-200 rounded-lg overflow-hidden bg-white">
               <button onClick={() => setLang('fa')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'fa' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500 hover:bg-gray-50'}`}>FA</button>
               <div className="w-px bg-gray-200"></div>
               <button onClick={() => setLang('en')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'en' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500 hover:bg-gray-50'}`}>EN</button>
            </div>
