           </div>
        ) : (
          <>
            {view === 'landing' && (
              <div className="animate-fade-in text-center py-12 md:py-20">
                <h2 className="text-3xl md:text-6xl font-black text-gray-900 mb-6 leading-tight whitespace-pre-line px-4">{lang === 'fa' ? (appConfig.landingHeroTitle || 'مسیر جهانی شدن کسب‌وکار شما') : 'Globalize Your Business'}</h2>
