                <div className="flex flex-col sm:flex-row gap-4 justify-center px-6">
                  <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl hover:scale-105 transition-transform">{t.startBtn}</button>
                  <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold hover:bg-gray-50 transition-colors">{t.trackBtn}</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mt-16 md:mt-24 px-4">
                  {t.features.map((f, i) => (
                    <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 group hover:border-indigo-200 transition-colors">
                        <div className="text-4xl mb-4 group-hover:scale-110 transition-transform">{[ '📂', '🌍', '📊'][i]}</div>
                        <h3 className="font-bold text-lg mb-2">{f.title}</h3>
                        <p className="text-gray-500 text-sm leading-relaxed">{f.desc}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {view === 'new-ticket' && (
              <CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} lang={lang} />
            )}

            {view === 'tracking' && (
              <TrackingView tickets={tickets} services={services} lang={lang} />
            )}

            {view === 'admin' && (
              <>
                {!currentUser ? (
                  <LoginView onLogin={handleLogin} onBack={() => setView('landing')} />
                ) : (
                  <AdminDashboard 
                    lang={lang}
                    currentUser={currentUser}
                    tickets={tickets} 
                    services={services}
                    personnel={personnel}
                    customers={customers}
                    messages={messages}
                    tasks={tasks}
                    meetings={meetings}
                    kpis={kpis}
                    config={appConfig}
                    onCreateTicket={async (t) => handleNewTicket(t)} 
                    onUpdateTicket={async (id, updates, actor, note, visibility) => {
                        const ticket = tickets.find(t => t.id === id);
                        if (!ticket) return;

                        // ایجاد رویداد جدید در تایم‌لاین برای ثبت در تاریخچه
                        const newTimelineEntry: TimelineEntry = {
                            type: updates.assignedTo ? 'assignment' : (updates.status ? 'status_change' : 'comment'),
                            title: updates.assignedTo ? 'ارجاع پرونده' : (updates.status ? `تغییر وضعیت به ${updates.status}` : 'بروزرسانی اطلاعات'),
                            description: note || '',
                            actorName: actor,
                            timestamp: new Date().toISOString(),
                            visibility: visibility || 'public'
                        };

                        const finalUpdates = {
                            ...updates,
                            timeline: [...(ticket.timeline || []), newTimelineEntry]
                        };

                        await updateTicketInCloud(id, finalUpdates);
                    }}
                    onDeleteTicket={deleteTicketFromCloud}
                    onUpdateServices={saveServicesToCloud}
                    onUpdatePersonnel={savePersonnelToCloud}
                    onUpdateCustomers={() => {}}
                    onEditCustomer={updateCustomerInCloud}
                    onDeleteCustomer={deleteCustomerFromCloud}
                    onUpdateConfig={saveAppConfigToCloud}
                    onLogout={handleLogout}
                  />
                )}
              </>
            )}
          </>
        )}
      </main>

      {/* Footer */}
      <footer className="hidden md:block bg-white border-t border-gray-200 py-8 text-center text-gray-500 text-sm">
        <p>{appConfig.footerText || t.footer}</p>
      </footer>

      {/* Mobile Bottom Navigation */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-200 px-2 py-1 flex items-center justify-around z-[60] shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <MobileNavItem 
          active={view === 'landing'} 
          label={t.home} 
          icon={<IconBulb />} 
          onClick={() => setView('landing')} 
        />
        <MobileNavItem 
          active={view === 'new-ticket'} 
          label={t.newTicket} 
          icon={<IconPlus />} 
          onClick={() => setView('new-ticket')} 
        />
        <MobileNavItem 
          active={view === 'tracking'} 
          label={t.tracking} 
          icon={<IconSearch />} 
          onClick={() => setView('tracking')} 
        />
        <MobileNavItem 
          active={view === 'admin'} 
          label={t.expertPanel} 
          icon={<IconLayout />} 
          onClick={() => setView('admin')} 
        />
      </div>
    </div>
  );
};

