import { IconLayout, IconPlus, IconSearch, IconShield, IconBulb, IconRefreshCw, IconAlertTriangle, IconCheck } from './components/Icons';
import { 
  saveTicketToCloud, updateTicketInCloud, deleteTicketFromCloud,
  saveCustomerToCloud, saveCustomersBulkToCloud, updateCustomerInCloud, deleteCustomerFromCloud,
  saveAppConfigToCloud,
  saveServicesToCloud,
  savePersonnelToCloud,
  subscribeToTickets, subscribeToCustomers, subscribeToSettings,
  subscribeToMessages, subscribeToTasks, subscribeToMeetings, subscribeToKPIs, sanitizeData, logSystemAction, checkDatabaseConnection
} from './services/firebaseService';

// Translations Dictionary
