};

const STORAGE_KEYS = { USER: 'crm_session_user', VIEW: 'crm_last_view', LAST_ACTIVE: 'crm_last_active' };

const App: React.FC = () => {
  const [view, setViewState] = useState<ViewState>('landing');
  const [lang, setLang] = useState<Language>('fa');
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [services, setServices] = useState<ServiceOption[]>(DEFAULT_SERVICES);
  const [personnel, setPersonnel] = useState<Personnel[]>(DEFAULT_PERSONNEL);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [messages, setMessages] = useState<InternalMessage[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [meetings, setMeetings] = useState<Meeting[]>([]);
  const [kpis, setKpis] = useState<KPI[]>([]);
  const [currentUser, setCurrentUser] = useState<Personnel | null>(null);
  const [appConfig, setAppConfig] = useState<AppConfig>(INITIAL_CONFIG);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [connectionStatus, setConnectionStatus] = useState<'connecting' | 'online' | 'offline'>('connecting');

  // جلوگیری از ارجاع تکراری در یک سشن
  const assignmentQueue = useRef<Set<string>>(new Set());

  const t = DICTIONARY[lang];

  const setView = (newView: ViewState) => {
    setViewState(newView);
    localStorage.setItem(STORAGE_KEYS.VIEW, newView);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCheckConnection = useCallback(async () => {
      setConnectionStatus('connecting');
      const isOnline = await checkDatabaseConnection();
      setConnectionStatus(isOnline ? 'online' : 'offline');
      return isOnline;
  }, []);

  /**
   * تابع محوری ارجاع خودکار
   * تغییرات: پشتیبانی از حالت ارجاع مستقیم (Fixed Definition)
   */
  const calculateAutoAssignee = useCallback((serviceIdOrTitle: string): string => {
      const config = appConfig.assignmentConfig;
      if (!config || config.mode === 'manual') return '';

      // ۱. پیدا کردن ID واقعی سرویس (چون گوگل فرم عنوان می‌فرستد)
      let actualServiceId = serviceIdOrTitle;
      const foundService = services.find(s => s.id === serviceIdOrTitle || s.title === serviceIdOrTitle);
      if (foundService) actualServiceId = foundService.id;

      // ۲. پیدا کردن نقش تعریف شده برای این سرویس
      const targetRole = config.serviceRoleMap[actualServiceId];
      if (!targetRole) return '';

      // ۳. پیدا کردن تمام پرسنل دارای این نقش که فعال هستند
      const eligiblePersonnel = personnel.filter(p => 
          p.roles && p.roles.includes(targetRole) && p.status === 'active'
      );

      if (eligiblePersonnel.length === 0) return '';

      // ۴. تصمیم‌گیری بر اساس حالت (Mode)

      // حالت الف: ارجاع مستقیم (تعریفی) - نفر اول لیست انتخاب می‌شود
      if (config.mode === 'direct_definition') {
          return eligiblePersonnel[0].id;
      }

      // حالت ب: توزیع بار کاری (آپشنال)
      if (config.mode === 'auto_load_balance') {
          const loadMap = eligiblePersonnel.map(p => {
              const count = tickets.filter(tk => tk.assignedTo === p.id && tk.status !== TicketStatus.COMPLETED).length;
              return { id: p.id, count };
          });
          loadMap.sort((a, b) => a.count - b.count);
          return loadMap[0].id;
      }

      // حالت ج: رندوم
      if (config.mode === 'random') {
          return eligiblePersonnel[Math.floor(Math.random() * eligiblePersonnel.length)].id;
      }

      return '';
  }, [appConfig, personnel, tickets, services]);

  /**
   * ناظر ارجاع (Monitor)
   * برای تیکت‌هایی که از گوگل فرم می‌آیند و فاقد ارجاع هستند
   */
  useEffect(() => {
      if (!appConfig.assignmentConfig || appConfig.assignmentConfig.mode === 'manual') return;

      const isManager = currentUser?.username === 'master' || currentUser?.roles.includes('مدیر');
      if (!isManager) return;

      const unassigned = tickets.filter(tk => !tk.assignedTo && tk.status === TicketStatus.SUBMITTED);

      unassigned.forEach(async (tk) => {
          if (assignmentQueue.current.has(tk.id)) return;

          const assigneeId = calculateAutoAssignee(tk.serviceId);
          if (assigneeId) {
              assignmentQueue.current.add(tk.id);
              const target = personnel.find(p => p.id === assigneeId);

              const updates: Partial<Ticket> = {
                  assignedTo: assigneeId,
                  timeline: [...(tk.timeline || []), {
                      type: 'assignment',
                      title: 'ارجاع خودکار سیستمی',
                      description: `پرونده به دلیل تنظیمات ارجاع مستقیم به ${target?.fullName} اختصاص یافت.`,
                      actorName: 'سیستم',
                      timestamp: new Date().toISOString(),
                      visibility: 'internal'
                  }]
              };

              try {
                  await updateTicketInCloud(tk.id, updates);
                  logSystemAction('UPDATE', 'Ticket', `ارجاع خودکار تیکت ${tk.id}`, 'System');
              } catch (e) {
                  console.error("Assignment Failed:", e);
              } finally {
                  assignmentQueue.current.delete(tk.id);
              }
          }
      });
  }, [tickets, appConfig.assignmentConfig, calculateAutoAssignee, currentUser, personnel]);

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'fa' ? 'rtl' : 'ltr';
    handleCheckConnection();

    const unsubTickets = subscribeToTickets(setTickets);
    const unsubCustomers = subscribeToCustomers(setCustomers);
    const unsubMessages = subscribeToMessages(setMessages);
    const unsubTasks = subscribeToTasks(setTasks);
    const unsubMeetings = subscribeToMeetings(setMeetings);
    const unsubKPIs = subscribeToKPIs(setKpis);
    const unsubSettings = subscribeToSettings(
      (cfg) => { if (cfg) setAppConfig(cfg); },
      (srv) => { if (srv) setServices(srv); },
      (ppl) => { if (ppl) { setPersonnel(ppl); setIsLoadingData(false); setConnectionStatus('online'); } }
    );

    return () => {
      unsubTickets(); unsubCustomers(); unsubSettings(); unsubMessages(); unsubTasks(); unsubMeetings(); unsubKPIs();
    };
  }, [handleCheckConnection, lang]);

  const handleLogin = async (u: string, p: string): Promise<boolean> => {
    const user = personnel.find(person => person.username === u && person.password === p);
    if (user) {
      setCurrentUser(user);
      logSystemAction('LOGIN', 'System', 'ورود به پنل', user.fullName, user.id);
      localStorage.setItem(STORAGE_KEYS.USER, JSON.stringify(sanitizeData(user)));
      return true;
    }
    return false;
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setView('landing');
    localStorage.removeItem(STORAGE_KEYS.USER);
  };

  const handleNewTicket = async (ticketOrTickets: Ticket | Ticket[]) => {
      const ticketsToSave = Array.isArray(ticketOrTickets) ? ticketOrTickets : [ticketOrTickets];
      for (const t of ticketsToSave) {
          const finalTicket = { ...t };
          // ارجاع در لحظه ثبت (اگر تنظیم شده باشد)
          const autoAssigneeId = calculateAutoAssignee(t.serviceId);
          if (autoAssigneeId) {
              finalTicket.assignedTo = autoAssigneeId;
              const target = personnel.find(p => p.id === autoAssigneeId);
              finalTicket.timeline.push({
                  type: 'assignment', title: 'ارجاع خودکار', description: `ارجاع به ${target?.fullName}`, actorName: 'سیستم', timestamp: new Date().toISOString(), visibility: 'internal'
              });
          }
          await saveTicketToCloud(finalTicket);
      }
  };

  const NavItem = ({ active, label, icon, onClick }: any) => (
    <button onClick={onClick} className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${active ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-600 hover:bg-gray-100'}`}>
      {icon}<span className="font-medium">{label}</span>
    </button>
  );

  const MobileNavItem = ({ active, label, icon, onClick }: any) => (
    <button onClick={onClick} className={`flex flex-col items-center justify-center gap-1 flex-1 py-2 transition-all ${active ? 'text-indigo-600' : 'text-gray-400'}`}>
      <div className={`p-1.5 rounded-xl transition-all ${active ? 'bg-indigo-50' : ''}`}>
        {React.cloneElement(icon as React.ReactElement, { className: 'w-6 h-6' })}
      </div>
      <span className="text-[10px] font-bold">{label}</span>
    </button>
  );

  return (
    <div className={`min-h-screen bg-gray-50 flex flex-col font-sans ${lang === 'fa' ? 'font-vazir' : ''}`} dir={lang === 'fa' ? 'rtl' : 'ltr'}>
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => setView('landing')}>
            <div className="bg-indigo-600 text-white p-2 rounded-lg"><IconShield className="w-6 h-6" /></div>
            <div className="hidden sm:block">
              <h1 className="text-xl font-bold text-gray-900 leading-tight">{lang === 'fa' ? appConfig.appTitle : appConfig.appTitleEn}</h1>
              <p className="text-[10px] text-gray-500">{lang === 'fa' ? appConfig.appSubtitle : appConfig.appSubtitleEn}</p>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div title={connectionStatus} className={`w-3.5 h-3.5 rounded-full border-2 border-white shadow-sm transition-all ${connectionStatus === 'online' ? 'bg-green-500 animate-pulse' : (connectionStatus === 'connecting' ? 'bg-yellow-400 animate-bounce' : 'bg-red-500')}`}></div>
            <nav className="hidden md:flex gap-2">
              <NavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus className="w-4 h-4" />} onClick={() => setView('new-ticket')} />
              <NavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch className="w-4 h-4" />} onClick={() => setView('tracking')} />
              <NavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout className="w-4 h-4" />} onClick={() => setView('admin')} />
            </nav>
            <div className="flex border border-gray-200 rounded-lg overflow-hidden bg-white">
               <button onClick={() => setLang('fa')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'fa' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500'}`}>FA</button>
               <button onClick={() => setLang('en')} className={`px-3 py-1 text-sm font-bold transition-colors ${lang === 'en' ? 'bg-indigo-100 text-indigo-700' : 'text-gray-500'}`}>EN</button>
            </div>
          </div>
        </div>
      </header>

      <main className="flex-grow p-4 md:p-8 max-w-7xl mx-auto w-full pb-24 md:pb-8">
        {isLoadingData && view !== 'landing' ? (
           <div className="flex items-center justify-center h-64"><div className="w-8 h-8 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div></div>
        ) : (
          <>
            {view === 'landing' && (
              <div className="animate-fade-in text-center py-12 md:py-20">
                <h2 className="text-3xl md:text-6xl font-black text-gray-900 mb-6 leading-tight whitespace-pre-line">{lang === 'fa' ? (appConfig.landingHeroTitle || 'مسیر جهانی شدن کسب‌وکار شما') : 'Globalize Your Business'}</h2>
                <p className="text-lg md:text-xl text-gray-600 mb-12 max-w-2xl mx-auto leading-relaxed">{lang === 'fa' ? (appConfig.landingHeroSubtitle || t.landingSubtitle) : t.landingSubtitle}</p>
                <div className="flex flex-col sm:flex-row gap-4 justify-center">
                  <button onClick={() => setView('new-ticket')} className="px-8 py-4 bg-indigo-600 text-white rounded-xl text-lg font-bold shadow-xl hover:scale-105 transition-transform">{t.startBtn}</button>
                  <button onClick={() => setView('tracking')} className="px-8 py-4 bg-white text-gray-700 border border-gray-200 rounded-xl text-lg font-bold hover:bg-gray-50 transition-colors">{t.trackBtn}</button>
                </div>
                {appConfig.featuredBusinesses && appConfig.featuredBusinesses.length > 0 && (
                    <div className="mt-20 border-t border-gray-100 pt-20">
                        <FeaturedBusinesses businesses={appConfig.featuredBusinesses} lang={lang} />
                    </div>
                )}
              </div>
            )}
            {view === 'new-ticket' && <CustomerForm config={appConfig} services={services.filter(s => s.isActive)} onSubmit={handleNewTicket} onCancel={() => setView('landing')} lang={lang} />}
            {view === 'tracking' && <TrackingView tickets={tickets} services={services} lang={lang} />}
            {view === 'admin' && (
              <>
                {!currentUser ? <LoginView onLogin={handleLogin} onBack={() => setView('landing')} /> : (
                  <AdminDashboard 
                    lang={lang} currentUser={currentUser} tickets={tickets} services={services} personnel={personnel} customers={customers} messages={messages} tasks={tasks} meetings={meetings} kpis={kpis} config={appConfig}
                    onCreateTicket={handleNewTicket} 
                    onUpdateTicket={(id, updates, actor, note, visibility) => {
                        const tk = tickets.find(t => t.id === id);
                        if (!tk) return;
                        const newEntry: TimelineEntry = {
                            type: updates.assignedTo ? 'assignment' : (updates.status ? 'status_change' : 'comment'),
                            title: updates.assignedTo ? 'ارجاع پرونده' : (updates.status ? `تغییر وضعیت به ${updates.status}` : 'بروزرسانی'),
                            description: note || '', actorName: actor, timestamp: new Date().toISOString(), visibility: visibility || 'public'
                        };
                        updateTicketInCloud(id, { ...updates, timeline: [...(tk.timeline || []), newEntry] });
                    }}
                    onDeleteTicket={deleteTicketFromCloud} onUpdateServices={saveServicesToCloud} onUpdatePersonnel={savePersonnelToCloud} onUpdateCustomers={() => {}} onEditCustomer={updateCustomerInCloud} onDeleteCustomer={deleteCustomerFromCloud} onUpdateConfig={saveAppConfigToCloud} onLogout={handleLogout}
                  />
                )}
              </>
            )}
          </>
        )}
      </main>

      <footer className="hidden md:block bg-white border-t border-gray-200 py-8 text-center text-gray-500 text-sm">
        <p>{appConfig.footerText || t.footer}</p>
      </footer>

      <div className="md:hidden fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-gray-200 px-2 py-1 flex items-center justify-around z-[60] shadow-[0_-4px_12px_rgba(0,0,0,0.05)]">
        <MobileNavItem active={view === 'landing'} label={t.home} icon={<IconBulb />} onClick={() => setView('landing')} />
        <MobileNavItem active={view === 'new-ticket'} label={t.newTicket} icon={<IconPlus />} onClick={() => setView('new-ticket')} />
        <MobileNavItem active={view === 'tracking'} label={t.tracking} icon={<IconSearch />} onClick={() => setView('tracking')} />
        <MobileNavItem active={view === 'admin'} label={t.expertPanel} icon={<IconLayout />} onClick={() => setView('admin')} />
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
