           <div className="lg:col-span-1 space-y-4">
              <div className="bg-gradient-to-r from-violet-600 to-indigo-600 rounded-2xl p-6 text-white text-center shadow-lg transform hover:scale-[1.02] transition-transform cursor-pointer" onClick={() => { setTargetFormForAi(isCustom ? 'custom' : 'main'); setShowAiModal(true); }}>
                  <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center mx-auto mb-3 backdrop-blur-sm"><IconMagic className="w-6 h-6 text-white" /></div>
                  <h3 className="font-bold text-lg mb-1">ساخت فرم با هوش مصنوعی</h3>
                  <p className="text-xs opacity-90">توضیح دهید، ما می‌سازیم.</p>
              </div>
              {editingFieldId ? (
                 <div className="bg-white p-6 rounded-2xl border border-indigo-200 shadow-md sticky top-6">
                    <h3 className="font-bold text-gray-800 mb-4 pb-2 border-b border-gray-100">{tempField.id?.startsWith('field-') ? 'افزودن فیلد جدید' : 'ویرایش فیلد'}</h3>
                    <div className="space-y-4">
                       <div><label className="block text-xs font-bold text-gray-500 mb-1">عنوان فیلد (فارسی)</label><input className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none" value={tempField.label || ''} onChange={(e) => setTempField({...tempField, label: e.target.value})} autoFocus /></div>
                       <div><label className="block text-xs font-bold text-gray-500 mb-1">نوع فیلد</label><select className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none bg-white" value={tempField.type} onChange={(e) => setTempField({...tempField, type: e.target.value as FormFieldType})} disabled={tempField.isSystem}><option value="text">متن تک خطی</option><option value="textarea">متن چند خطی</option><option value="tel">شماره تماس</option><option value="email">ایمیل</option><option value="select">لیست کشویی</option><option value="checkbox">چک‌باکس</option><option value="date">تاریخ</option><option value="header">تیتر جداکننده</option></select></div>
                       {tempField.type === 'select' && (<div><label className="block text-xs font-bold text-gray-500 mb-1">گزینه‌ها (با ویرگول جدا کنید)</label><textarea className="w-full px-3 py-2 rounded-lg border border-gray-300 text-sm focus:border-indigo-500 outline-none" placeholder="گزینه 1, گزینه 2" rows={4} value={tempField.options?.join(', ') || ''} onChange={(e) => setTempField({...tempField, options: e.target.value.split(',').map(o => o.trim())})} /></div>)}
                       <div className="flex items-center gap-2 py-2"><input type="checkbox" checked={tempField.required} onChange={(e) => setTempField({...tempField, required: e.target.checked})} id="req_check" className="w-4 h-4 text-indigo-600 rounded focus:ring-indigo-500 cursor-pointer" /><label htmlFor="req_check" className="text-sm font-medium text-gray-700 cursor-pointer select-none">این فیلد اجباری باشد</label></div>
                       <div className="flex gap-3 pt-2"><button onClick={handleSaveField} className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl text-sm font-bold hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100">{tempField.id?.startsWith('field-') ? 'افزودن' : 'بروزرسانی'}</button><button onClick={() => {setEditingFieldId(null); setTempField({});}} className="flex-1 bg-white border border-gray-300 text-gray-600 py-2.5 rounded-xl text-sm font-bold hover:bg-gray-50 transition-colors">انصراف</button></div>
                    </div>
                 </div>
              ) : (
                 <div className="bg-white border border-dashed border-gray-300 rounded-2xl p-8 text-center sticky top-6 hover:border-indigo-300 transition-colors"><button onClick={handleAddField} className="w-full bg-gray-50 text-gray-700 hover:bg-gray-100 py-3 rounded-xl font-bold transition-colors flex items-center justify-center gap-2 border border-gray-200"><IconPlus className="w-5 h-5" />افزودن فیلد دستی</button></div>
              )}
           </div>
           <div className="lg:col-span-2 bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden flex flex-col"><div className="p-5 bg-gray-50 border-b border-gray-100 flex justify-between items-center"><h3 className="font-bold text-gray-800 flex items-center gap-2"><IconLayout className="w-5 h-5 text-indigo-600" />پیش‌نمایش ساختار فرم</h3><span className="text-xs font-bold bg-white px-2 py-1 rounded border border-gray-200 text-gray-500">{fields.length} فیلد</span></div><div className="divide-y divide-gray-100 max-h-[600px] overflow-y-auto">{fields.length === 0 && <div className="p-8 text-center text-gray-400">هنوز فیلدی اضافه نشده است.</div>}{fields.map((field, index) => (<div key={field.id} className="p-4 flex items-center justify-between hover:bg-gray-50 group transition-colors"><div className="flex items-center gap-4"><div className="flex flex-col gap-1"><button onClick={() => moveField(index, 'up')} className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-200 text-gray-400 hover:text-indigo-600 disabled:opacity-20 transition-colors" disabled={index === 0}>▲</button><button onClick={() => moveField(index, 'down')} className="w-6 h-6 flex items-center justify-center rounded hover:bg-gray-200 text-gray-400 hover:text-indigo-600 disabled:opacity-20 transition-colors" disabled={index === fields.length - 1}>▼</button></div><div><div className="font-bold text-gray-800 text-sm flex items-center gap-2">{field.type === 'header' && <span className="w-2 h-2 rounded-full bg-indigo-500"></span>}{field.label}{field.required && <span className="text-red-500">*</span>}</div><div className="text-xs text-gray-400 mt-1 font-mono flex gap-2"><span className="bg-gray-50 px-1 rounded">{field.type}</span></div></div></div><div className="flex items-center gap-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity"><button onClick={() => handleEditField(field)} className="p-2 text-blue-600 bg-blue-50 rounded-lg hover:bg-blue-100 hover:scale-110 transition-all"><IconEdit className="w-4 h-4" /></button>{!field.isSystem && (<button onClick={() => handleDeleteField(field.id)} className="p-2 text-red-600 bg-red-50 rounded-lg hover:bg-red-100 hover:scale-110 transition-all"><IconTrash className="w-4 h-4" /></button>)}</div></div>))}</div></div>
      </div>
  );

  return (
    <div className="space-y-6 animate-fade-in relative">
      {showAiModal && (<div className="fixed inset-0 z-[60] flex items-center justify-center bg-gray-900/60 backdrop-blur-sm p-4"><div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl p-8 relative overflow-hidden"><div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-violet-500 to-fuchsia-500"></div><h3 className="text-2xl font-black text-gray-800 mb-2 flex items-center gap-2"><IconMagic className="w-6 h-6 text-violet-600" />تولید فرم هوشمند</h3><textarea className="w-full border-2 border-gray-200 rounded-xl p-4 text-sm focus:border-violet-500 focus:ring-4 focus:ring-violet-100 outline-none transition-all mb-6" rows={4} placeholder="توضیحات فرم..." value={aiPrompt} onChange={(e) => setAiPrompt(e.target.value)} /><div className="flex gap-3"><button onClick={() => setShowAiModal(false)} className="flex-1 py-3 text-gray-600 font-bold hover:bg-gray-50 rounded-xl transition-colors">انصراف</button><button onClick={handleAiGenerate} disabled={isGenerating || !aiPrompt.trim()} className="flex-1 py-3 bg-violet-600 text-white font-bold rounded-xl hover:bg-violet-700 transition-all shadow-lg shadow-violet-200 flex justify-center items-center gap-2">{isGenerating ? '...' : 'ساخت فرم'}</button></div></div></div>)}

      <div className="flex bg-white p-1 rounded-xl border border-gray-100 w-fit shadow-sm overflow-x-auto max-w-full">
        {['general', 'assignment', 'form', 'custom_forms', 'google_forms', 'daily', 'businesses'].map(tab => (
            <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap flex items-center gap-2 ${activeTab === tab ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}>{tab === 'general' ? <IconSettings className="w-4 h-4" /> : tab === 'assignment' ? <IconUsers className="w-4 h-4" /> : tab === 'form' ? <IconLayout className="w-4 h-4" /> : tab === 'custom_forms' ? <IconClipboard className="w-4 h-4" /> : tab === 'google_forms' ? <IconLink className="w-4 h-4" /> : tab === 'daily' ? <IconBulb className="w-4 h-4" /> : <IconBriefcase className="w-4 h-4" />}{tab === 'general' ? 'عمومی' : tab === 'assignment' ? 'ارجاع کار' : tab === 'form' ? 'فرم اصلی' : tab === 'custom_forms' ? 'فرم‌ها' : tab === 'google_forms' ? 'گوگل فرم' : tab === 'daily' ? 'نکات' : 'تبلیغات'}</button>
        ))}
      </div>

      {activeTab === 'assignment' && isMaster && (
          <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-sm animate-fade-in">
              <div className="flex items-center gap-3 mb-6">
                  <div className="p-2 bg-indigo-100 text-indigo-600 rounded-lg"><IconUsers className="w-5 h-5" /></div>
                  <div>
                      <h3 className="text-lg font-bold text-gray-800">سیستم ارجاع کار هوشمند</h3>
                      <p className="text-sm text-gray-500">تعیین نحوه تخصیص تیکت‌های جدید به پرسنل</p>
                  </div>
              </div>

              <div className="space-y-6">
                  <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                      <label className="block text-sm font-bold text-gray-700 mb-3">حالت ارجاع (Assignment Mode)</label>
                      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                          <button onClick={() => setAssignmentConfig(prev => ({ ...prev, mode: 'manual' }))} className={`p-4 rounded-xl border-2 text-center transition-all ${assignmentConfig.mode === 'manual' ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'border-gray-200 bg-white hover:border-indigo-200'}`}>
                              <div className="font-bold mb-1">دستی</div>
                              <div className="text-[10px] opacity-70">ارجاع توسط مدیر</div>
                          </button>
                          <button onClick={() => setAssignmentConfig(prev => ({ ...prev, mode: 'direct_definition' }))} className={`p-4 rounded-xl border-2 text-center transition-all ${assignmentConfig.mode === 'direct_definition' ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'border-gray-200 bg-white hover:border-indigo-200'}`}>
                              <div className="font-bold mb-1">تعریف مستقیم</div>
                              <div className="text-[10px] opacity-70">ارجاع به نقش مشخص شده</div>
                          </button>
                          <button onClick={() => setAssignmentConfig(prev => ({ ...prev, mode: 'auto_load_balance' }))} className={`p-4 rounded-xl border-2 text-center transition-all ${assignmentConfig.mode === 'auto_load_balance' ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'border-gray-200 bg-white hover:border-indigo-200'}`}>
                              <div className="font-bold mb-1">کمترین بار کاری</div>
                              <div className="text-[10px] opacity-70">توزیع عادلانه (هوشمند)</div>
                          </button>
                          <button onClick={() => setAssignmentConfig(prev => ({ ...prev, mode: 'random' }))} className={`p-4 rounded-xl border-2 text-center transition-all ${assignmentConfig.mode === 'random' ? 'border-indigo-600 bg-indigo-50 text-indigo-800' : 'border-gray-200 bg-white hover:border-indigo-200'}`}>
                              <div className="font-bold mb-1">تصادفی</div>
                              <div className="text-[10px] opacity-70">توزیع اتفاقی</div>
                          </button>
                      </div>
                  </div>

                  {(assignmentConfig.mode !== 'manual') && (
                      <div className="bg-white border border-gray-200 rounded-xl overflow-hidden animate-slide-in">
                          <div className="bg-gray-50 px-6 py-4 border-b border-gray-200 font-bold text-gray-700">تعریف ارجاع برای هر خدمت</div>
                          <div className="divide-y divide-gray-100">
                              {services.map(service => (
                                  <div key={service.id} className="flex items-center justify-between px-6 py-4 hover:bg-gray-50">
                                      <div className="flex items-center gap-3">
                                          <span className="text-xl">{service.icon}</span>
                                          <span className="text-sm font-bold text-gray-800">{service.title}</span>
                                      </div>
                                      <div className="flex items-center gap-2">
                                          <span className="text-xs text-gray-500">ارجاع به نقش:</span>
                                          <select 
                                              className="border border-gray-300 rounded-lg px-3 py-1.5 text-sm bg-white outline-none focus:border-indigo-500"
                                              value={assignmentConfig.serviceRoleMap[service.id] || ''}
                                              onChange={(e) => setAssignmentConfig(prev => ({ ...prev, serviceRoleMap: { ...prev.serviceRoleMap, [service.id]: e.target.value } }))}
                                          >
                                              <option value="">-- انتخاب نقش --</option>
                                              {config.personnelRoles?.map(role => <option key={role} value={role}>{role}</option>)}
                                          </select>
                                      </div>
                                  </div>
                              ))}
                          </div>
                      </div>
                  )}

                  <div className="flex justify-end pt-4">
                      {saveSuccess && <span className="text-green-600 font-bold ml-4 self-center animate-fade-in">ذخیره شد.</span>}
                      <button onClick={saveSettings} disabled={isSaving} className="bg-indigo-600 text-white px-8 py-3 rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700">
                          {isSaving ? '...' : 'ذخیره تنظیمات ارجاع'}
                      </button>
                  </div>
              </div>
          </div>
      )}

      {activeTab === 'general' && (
        <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm relative overflow-hidden">
           <div className="flex items-center gap-3 mb-6"><div className="p-2 bg-gray-100 text-gray-600 rounded-lg"><IconSettings className="w-5 h-5" /></div><h3 className="text-lg font-bold text-gray-800">مشخصات عمومی</h3></div>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
              <div><label className="block text-sm font-bold text-gray-700 mb-2">عنوان سایت</label><input className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-indigo-500 outline-none" value={generalData.appTitle} onChange={(e) => handleGeneralChange('appTitle', e.target.value)} /></div>
              <div className="md:col-span-2 border-t border-gray-100 pt-6 mt-2"><h4 className="font-bold text-indigo-800 mb-4">متون صفحه فرود</h4></div>
              <div className="md:col-span-2"><label className="block text-sm font-bold text-gray-700 mb-2">تیتر اصلی</label><input className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-indigo-500 outline-none" value={generalData.landingHeroTitle} onChange={(e) => handleGeneralChange('landingHeroTitle', e.target.value)} /></div>
              <div className="md:col-span-2"><label className="block text-sm font-bold text-gray-700 mb-2">توضیحات</label><textarea className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-indigo-500 outline-none" value={generalData.landingHeroSubtitle} onChange={(e) => handleGeneralChange('landingHeroSubtitle', e.target.value)} rows={2} /></div>
           </div>
           <div className="flex items-center justify-end pt-6"><button onClick={saveSettings} disabled={isSaving} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold">{isSaving ? '...' : 'ذخیره تغییرات'}</button></div>
        </div>
      )}
      {/* Remaining tabs logic (daily, businesses, form, custom_forms, google_forms, invoice, maintenance) remains the same as previous version but integrated in this container */}
    </div>
  );
};
